# Mg+ 3s -> 3p against the relativistic distorted-wave (RDW) code with and without its non-local exchange, at 10 and 20 eV.
#
# The RDW reference is generated by work/rdw-mg/runref.sh (the Fortran code built there with legacy semantics; its static
# run reproduces the stored ics2p3.dat to 1e-6). The two pairs compared are the SAME physics:
#   RDW iter = 0   (static waves, no projection)        <->  JAC continuumExchange = :none
#   RDW iter = 40  (non-local exchange, wpq; the wave     <->  JAC continuumExchange = :nonlocal, orthogonalizeContinuum = true
#                  is projected on every same-kappa bound orbital each iteration)
# Both codes add the exact exchange AMPLITUDE. What does NOT cancel is the atomic structure (the excitation energies are
# printed) and the partial-wave treatment, which is why the ratio RDW(exch)/RDW(static) is compared with the JAC ratio.
#
# Run from <JAC-root>:   OPENBLAS_NUM_THREADS=2 julia --project=. -t 2 tools/benchmark-ie-MgII-exchange.jl

using JenaAtomicCalculator, Printf
const JAC = JenaAtomicCalculator
using JenaAtomicCalculator: ImpactExcitation

setDefaults("unit: energy", "eV")
setDefaults("method: continuum, Galerkin")
setDefaults("method: normalization, Alok")

const GRID = Radial.Grid(Radial.Grid(true), rnt = 2.0e-6, h = 5.0e-2, hp = 1.0e-2, rbox = 25.0)

function sigmas(exch, orth)
    set = ImpactExcitation.Settings(ImpactExcitation.Settings(); electronEnergies = [10.0, 20.0], calcRateCoefficient = false,
                                    maxKappa = 40, printBefore = false, asymptoticTail = true, topUp = true,
                                    continuumExchange = exch, orthogonalizeContinuum = orth)
    wa  = Atomic.Computation(Atomic.Computation(), name="Mg+", grid=GRID, nuclearModel=Nuclear.Model(12.),
                             initialConfigs=[Configuration("[Ne] 3s")], finalConfigs=[Configuration("[Ne] 3p")], processSettings=set)
    st  = redirect_stdout(devnull) do;   @timed perform(wa, output=true)[ImpactExcitation.Settings]   end
    return( st.value, st.time )
end

(a, ta) = sigmas(:none, false);   (b, tb) = sigmas(:nonlocal, true)
println("\n=== JAC, Mg+ 3s -> 3p, maxKappa = 40 + top-up, tail on: sigma [a0^2] ===")
@printf("  %6s %-6s %12s %16s %10s\n", "E [eV]", "J_f", "static", "nonlocal+orth", "ratio")
for  i in eachindex(a)
    @printf("  %6.1f %-6s %12.4f %16.4f %10.4f\n", Defaults.convertUnits("energy: from atomic to eV", a[i].initialElectronEnergy),
            string(a[i].finalLevel.J), a[i].crossSection, b[i].crossSection, b[i].crossSection/a[i].crossSection)
end
@printf("  wall time: static %.1f s, nonlocal+orth %.1f s\n", ta, tb)
println("\n=== RDW (work/rdw-mg/reference.txt) ===")
isfile("work/rdw-mg/reference.txt") && print(read("work/rdw-mg/reference.txt", String))
